WITH unpacked AS (SELECT id, created_at, ship_to, attributes, COALESCE(attributes['device'], 'direct') AS device_or_default, TRANSFORM(FILTER(items, i -> i.promo IS NOT NULL), i -> STRUCT(i.product_id AS pid, ROUND(i.price * 0.9, 2) AS discounted_price)) AS promo_lines FROM carts) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, COUNT(*) AS event_count, MIN(created_at) AS first_created_at, MAX(created_at) AS ended_at, MIN(created_at) AS first_seen FROM unpacked GROUP BY DATE_TRUNC('HOUR', created_at) HAVING event_count < 1
